```javascript
function esPrimo(numero) {
  // Si el número es 2 o 3, es primo
  if (numero === 2 || numero === 3) {
    return true;
  }
  // Si el número es divisible por 2 o 3, no es primo
  if (numero % 2 === 0 || numero % 3 === 0) {
    return false;
  }
  // Si el número es mayor que 3, verifica si es divisible por algún número entre 4 y la raíz cuadrada del número
  for (let I = 4; I <= Math.sqrt(numero); I += 2) {
    if (numero % I === 0) {
      return false;
    }
  }
  // Si no es divisible por ningún número entre 4 y la raíz cuadrada del número, es primo
  return true;
}

function verificaPrimos(arrayNumeros) {
  for (let I = 0; I < arrayNumeros.length; i++) {
    const numero = arrayNumeros[i];
    if (esPrimo(numero)) {
      console.log(`El número ${numero} es primo`);
    }
  }
}

// Ejemplo de uso
